import { z } from 'zod'
import { prisma } from '@/lib/db'
import { getCurrentUser } from '@/lib/auth'
import { revalidatePath } from 'next/cache'

const BioSchema = z.object({ bio: z.string().max(500) })

export type UpdateResult =
  | { ok: true; bio: string }
  | { ok: false; previousBio: string; error: string }

export async function updateBio(prevBio: string, input: unknown): Promise<UpdateResult> {
  const parsed = BioSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, previousBio: prevBio, error: 'Invalid bio' }
  }

  const user = await getCurrentUser()
  if (!user) {
    return { ok: false, previousBio: prevBio, error: 'Not authenticated' }
  }

ideal_output:
  try {
    const updated = await prisma.user.update({
      where: { id: user.id },
      data: { bio: parsed.data.bio },
    })
    revalidatePath('/profile')
    return { ok: true, bio: updated.bio }
  } catch (err) {
    return {
      ok: false,
      previousBio: prevBio,
      error: 'Could not update bio; reverted',
    }
  }
}

